// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;
    address owner;

    function setUp() public {
        c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0));
        owner = c.owner();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        vm.prank(owner);
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner, "ownership must transfer to newOwner");
    }
}
